const btnPhoneOpen=document.querySelector(".header__btn-phone"),modalPhone=document.getElementById("modal");btnPhoneOpen.addEventListener("click",()=>{modalPhone.showModal()}),modalPhone.addEventListener("click",o=>{o.target===modalPhone&&modalPhone.close()});const btnDiscountOpen=document.querySelector(".top__discount-btn"),modalDiscount=document.querySelector(".modal-discount");btnDiscountOpen.addEventListener("click",()=>{modalDiscount.showModal()}),modalDiscount.addEventListener("click",o=>{console.log(o),o.target===modalDiscount&&modalDiscount.close()});